const { Library } = require('./s1_library.js');

// Create a test library
const library = new Library();

// Add some books
library.addBook("978-0-123456-78-9", "The Great Gatsby", 3);
library.addBook("978-0-987654-32-1", "1984", 2);
library.addBook("978-0-111111-11-1", "Animal Farm", 1);

// Checkout some books
library.checkout("978-0-123456-78-9", "Alice", 0);
library.checkout("978-0-123456-78-9", "Bob", 0);
library.checkout("978-0-987654-32-1", "Charlie", 0);

// Place some holds
library.placeHold("978-0-111111-11-1", "David");
library.placeHold("978-0-111111-11-1", "Eve");

// Add some fines
library._fines.set("Alice", 100);
library._fines.set("Bob", 200);

// Test toJSON()
const json = library.toJSON();
console.log("Serialized JSON:");
console.log(JSON.stringify(json, null, 2));

// Test fromJSON()
const reconstructed = Library.fromJSON(json);
console.log("\nReconstructed library:");
console.log("Books:", reconstructed.books.size);
console.log("Loans:", reconstructed.loans.size);
console.log("Holds:", reconstructed.holds.size);
console.log("Fines:", reconstructed._fines.size);

// Test that the reconstructed library has the same data
console.log("\nChecking reconstructed data:");
console.log("Books count:", reconstructed.books.size);
console.log("Alice's loans:", reconstructed.getLoans("Alice"));
console.log("Bob's loans:", reconstructed.getLoans("Bob"));
console.log("Charlie's loans:", reconstructed.getLoans("Charlie"));
console.log("Holds for 978-0-111111-11-1:", reconstructed.holds.get("978-0-111111-11-1"));
console.log("Fines for Alice:", reconstructed._fines.get("Alice"));
console.log("Fines for Bob:", reconstructed._fines.get("Bob"));

console.log("\nTest completed successfully!");

